from AlgorithmImports import *
from collections import deque
import math


class ExactStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy_closes = deque(maxlen=201)
        self.aapl_closes = deque(maxlen=4)
        self.aapl_red_streak = 0

        self.spy_sma50 = None
        self.spy_sma200 = None

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.aapl_rsi_values = deque(maxlen=2)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        self.SetWarmUp(201, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = {}

        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                return
            bars[ticker] = data.Bars[symbol]

        spy_bar = bars["SPY"]
        aapl_bar = bars["AAPL"]

        previous_spy_sma50 = self.spy_sma50
        previous_spy_sma200 = self.spy_sma200

        if len(self.spy_closes) >= 50:
            self.spy_sma50 = sum(list(self.spy_closes)[-50:]) / 50.0

        if len(self.spy_closes) >= 200:
            self.spy_sma200 = sum(list(self.spy_closes)[-200:]) / 200.0

        if len(self.aapl_closes) > 0:
            previous_aapl_close = self.aapl_closes[-1]
            if aapl_bar.Close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.spy_closes.append(float(spy_bar.Close))
        self.aapl_closes.append(float(aapl_bar.Close))

        self.aapl_rsi.Update(aapl_bar.EndTime, float(aapl_bar.Close))
        if self.aapl_rsi.IsReady:
            self.aapl_rsi_values.append(float(self.aapl_rsi.Current.Value))

        if self.IsWarmingUp:
            return

        spy_close = float(spy_bar.Close)
        aapl_close = float(aapl_bar.Close)

        if (
            self.strategy_a_shares > 0
            and previous_spy_sma50 is not None
            and self.spy_sma50 is not None
            and len(self.spy_closes) >= 2
        ):
            previous_close = list(self.spy_closes)[-2]
            sell_a = (
                previous_close >= previous_spy_sma50
                and spy_close < self.spy_sma50
            )

            if sell_a:
                self.MarketOrder(
                    self.symbols["SPY"],
                    -self.strategy_a_shares
                )
                self.strategy_a_shares = 0

        if (
            self.strategy_b_shares > 0
            and self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > 60
        ):
            self.MarketOrder(
                self.symbols["AAPL"],
                -self.strategy_b_shares
            )
            self.strategy_b_shares = 0

        if (
            self.strategy_a_shares == 0
            and previous_spy_sma200 is not None
            and self.spy_sma200 is not None
            and len(self.spy_closes) >= 2
        ):
            previous_close = list(self.spy_closes)[-2]
            buy_a = (
                previous_close <= previous_spy_sma200
                and spy_close > self.spy_sma200
            )

            if buy_a:
                target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                quantity = int(math.floor(target_value / spy_close))
                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity)
                    self.strategy_a_shares = quantity

        if (
            self.strategy_b_shares == 0
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20000
        ):
            quantity = int(math.floor(20000 / aapl_close))
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.strategy_b_shares = quantity

