        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data: Slice):
        available = {symbol: data.Bars.ContainsKey(symbol) for symbol in self.symbols}

        if available[self.spy]:
            spy_close = data.Bars[self.spy].Close

            if self.spy_sma_200.IsReady:
                if self.spy_previous_close is not None and self.spy_previous_sma_200 is not None:
                    strategy_a_buy = (
                        self.spy_previous_close <= self.spy_previous_sma_200
                        and spy_close > self.spy_sma_200.Current.Value
                    )
                else:
                    strategy_a_buy = False
            else:
                strategy_a_buy = False

            if self.spy_sma_50.IsReady:
