                        self.spy_previous_close >= self.spy_previous_sma_50
                        and spy_close < self.spy_sma_50.Current.Value
                    )
                else:
                    strategy_a_sell = False
            else:
                strategy_a_sell = False

            current_sma_200 = (
                self.spy_sma_200.Current.Value if self.spy_sma_200.IsReady else None
            )
            current_sma_50 = (
                self.spy_sma_50.Current.Value if self.spy_sma_50.IsReady else None
            )
        else:
            strategy_a_buy = False
            strategy_a_sell = False
            spy_close = None
            current_sma_200 = None
            current_sma_50 = None

        if available[self.aapl]:
            aapl_bar = data.Bars[self.aapl]
            aapl_close = aapl_bar.Close

            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            else:
                self.aapl_red_streak = 0

            strategy_b_buy = (
                self.aapl_red_streak >= 3
                and self.aapl_rsi_14.IsReady
            )
            strategy_b_sell = (
                self.aapl_rsi_14.IsReady
                and self.aapl_rsi_14.Current.Value > 60
            )
        else:
            strategy_b_buy = False
            strategy_b_sell = False
            aapl_close = None

        if not all(available.values()) or self.IsWarmingUp:
            self._update_previous_state(
                spy_close, current_sma_200, current_sma_50, aapl_close
            )
